/*	The error trigger payload carries workflow and execution metadata only,	*/
/*	never the failing run's own data, so there is no event id here to anchor	*/
/*	an Administrate external log against. nodeId on createExternalIntegrationLog	*/
/*	is ID! and record scoped, which is why this writes to a Data Table instead	*/
/*	of back into Administrate.	*/

/*	execution.url on the payload can resolve to http://localhost:5678 when the	*/
/*	instance has no editor base URL configured, so the link would be dead.	*/
/*	Build it from your real n8n host instead. Change this line to match it.	*/
const instanceBase_str = 'https://YOUR-N8N-HOST';

const payload_obj = $json || {};
const workflow_obj = payload_obj.workflow || {};
const execution_obj = payload_obj.execution || {};
const error_obj = execution_obj.error || {};

let message_str = String(error_obj.message || '').trim();

if (message_str === '')
{
	message_str = 'The trigger payload carried no error message';
}

const workflowId_str = String(workflow_obj.id || '');
const executionId_str = String(execution_obj.id || '');
let url_str = '';

if (workflowId_str !== '' && executionId_str !== '')
{
	url_str = instanceBase_str + '/workflow/' + workflowId_str + '/executions/' + executionId_str;
}

return [{ json: {
	failed_at: DateTime.now().toISO(),
	workflow_name: String(workflow_obj.name || ''),
	workflow_id: workflowId_str,
	execution_id: executionId_str,
	execution_url: url_str,
	execution_mode: String(execution_obj.mode || ''),
	last_node: String(execution_obj.lastNodeExecuted || ''),
	error_message: message_str.slice(0, 2000)
} }];
